def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x()
    target_x = 26.0

    # Stop if the vehicle has reached or exceeded the target
    if front_x >= target_x + 0.1:
        return

    # Apply thrust every 3 steps to respect cooldown
    if step_count % 3 == 0:
        vx = agent_body.linearVelocity.x

        # Adjust thrust to prevent exceeding speed cap
        if vx > 3.5:
            fx = 520.0 * 0.1  # 10% thrust if near speed limit
        elif vx > 1.0:
            fx = 520.0 * 0.4  # 40% thrust at moderate speed
        else:
            fx = 520.0  # Full thrust at low speed

        # Apply forward thrust
        sandbox.apply_force(agent_body, fx, 0.0, step_count=step_count)
